const p=document.querySelector('.progress');onscroll=()=>p.style.width=100*scrollY/(document.documentElement.scrollHeight-innerHeight)+'%';const o=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add('on')),{threshold:.15});document.querySelectorAll('.sec').forEach(x=>o.observe(x));const flow=(document.body.dataset.flow||'Question|Definition|Data|Control|Decision').split('|');document.querySelectorAll('.stage').forEach(s=>s.innerHTML=flow.map((x,i)=>'<b class=node>'+x+'</b>'+(i<flow.length-1?'<span class=arrow>→</span>':'')).join(''));